quests[35352] = { id = 35352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonusbelohnung: Schwarzfelshöhlen" }
quests[35353] = { id = 35353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Teil des Puzzles", description = "Jetzt erinnere ich mich. Wachkommandant Branson hatte uns aufgetragen, im Gasthaus zu bleiben... Er meinte, wir wären dort sicher.\n\nUnd dann...\n\nDann brach dieses DING durch und schlachtete alle ab!\n\nDas Letzte, woran ich mich erinnere, ist, wie das Monstrum in die Vorratskammer hinabstieg.", sourceObjective = "Tötet die schreckliche Anomalie im Keller des Gasthauses.", progress = "Ist diese Kreatur tot?", completion = "Ich werde die anderen von unserem Schicksal überzeugen. Sie können es nicht mehr ignorieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[35356] = { id = 35356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jemandem fehlt ein Pfeil", description = "<Ein Pfeil der Rangari steckt in der Flanke dieses Talbuks. Vielleicht hat ja Rangari Laara Interesse an Eurem Fund.>", sourceObjective = "Bringt den Rangaripfeil zu Rangari Laara in der Telaaristation.\n\nBereitgestellter Gegenstand:", completion = "Das ist MEIN Pfeil! Wo habt Ihr den her?", sourceObjectiveStatus = "unverified-source-field" }
quests[35357] = { id = 35357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König der Brisenschreiter", description = "Lasst mich raten: Er steckte in der Flanke eines Talbuks?\n\n<Laara wirkt für einen Moment gedankenversunken.>\n\nMit diesem Pfeil wollte ich Hochrücken, den König der Brisenschreiter, erlegen. Aber gerade als ich ihn abfeuerte, ist der Talbuk, den Ihr erlegt habt, in die Schussbahn gesprungen.\n\nIch schlage vor, dass Ihr Jagd auf den König macht. Als ich hinter ihm her war, schien er den Teich bei den Einsamen Fällen im Süden aufsuchen zu wollen.", sourceObjective = "Besorgt Hochrückens Schweif.", progress = "Wie läuft die Jagd auf Hochrücken?", completion = "Gut gemacht, {name}. Ihr habt vollbracht, was mir nicht gelungen ist.\n\nVielleicht seid Ihr Fremden doch keine so schlechten Jäger.", sourceObjectiveStatus = "unverified-source-field" }
quests[35358] = { id = 35358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "End Time Reward Quest" }
