quests[35371] = { id = 35371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Ogerbeute 005" }
quests[35372] = { id = 35372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Oshu'gun", description = "Die Elemente haben gesprochen und uns eine Vision zukommen lassen, {name}.\n\nWir werden zusammen zum großen Berg Oshu'gun reisen und dem finsteren Einfluss dort ein Ende machen.\n\nWenn die Bilder Eurer Vision nicht trügen, erwarten uns große Gefahren.\n\nWir treffen uns im Geisterwald am Fuße des Oshu'gun. Wenn Ihr bereit seid, aufzubrechen, dann sprecht mit Gixmo Goldscheffel und er wird Euch hinfliegen.", sourceObjective = "Fliegt zum Geisterwald.", completion = "Diese Wälder sind den Orcs wie auch meinem Volk heilig.\n\nUnter dem großen Berg Oshu'gun liegt das Herz von Nagrand: das Genedar. Dieses riesige Dimensionsgefährt bewahrte mein Volk vor der Auslöschung und brachte uns in diese Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[35373] = { id = 35373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Ogerbeute 006" }
quests[35374] = { id = 35374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stampfende Geräusche", description = "Kommandant, die Frostwölfin und ich haben gerade die Vorteile verschiedener \"Jagdmethoden\" erörtert.\n\nIch konnte ihr versichern, dass die Schattenjäger für jede Situation gewappnet sind – auch in der Wildnis.\n\nSie aber glaubt, dass wir in \"ihrem Land\" nicht in der Lage sind, Beute zu machen.\n\nWir sollten sie davon überzeugen, dass sie sich irrt. Gehen wir ein paar Grollhufe jagen.", sourceObjective = "Sammelt 12 Paar Lederhautohren von Lederhautgrollhufen.", progress = "Unglaublich, wie arrogant diese Frostwölfe sein können.", completion = "Zwölf Paare also? Das ist ziemlich gut, Kommandant.\n\nHm, ich glaube, so viele habe ich nicht erbeuten können. Ich hab... ungefähr ein Dutzend Ohrenpaare. Tja...", sourceObjectiveStatus = "unverified-source-field" }
quests[35375] = { id = 35375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Königin der Grollhufe", description = "Ogka sagte mir, dass Banthar in der Nähe ist! Oder vielmehr, dass sie hier immer noch am Leben sei. Wisst Ihr, was ich meine?\n\nDas ist unsere Gelegenheit, Kommandant. Wir können eine jüngere und mächtigere Ausgabe von Banthar erlegen und diesen Frostwölfen eine Lektion erteilen.\n\nWir werden Ogka zeigen, wie echte Profis arbeiten.", sourceObjective = "Besorgt das Horn von Banthar.", progress = "Das Horn von Banthar. Hemet würde alles dafür geben, eine solch mächtige Bestie erlegen zu dürfen.", completion = "Ein Triumph, Kommandant. Ihr habt uns alle stolz gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[35376] = { id = 35376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdwettstreit", description = "Taz und ich befinden uns in einem Wettstreit darüber, wer sich besser auf das Jagdhandwerk versteht: Schattenjäger oder Frostwölfe.\n\nWollt Ihr vielleicht in diesen Wettkampf einsteigen, Kommandant?\n\nIch habe mir die wilden, majestätischen Talbuks als bevorzuge Beute ausgesucht. Wie alle Bewohner Draenors wissen, repräsentieren sie die ganze Pracht von Nagrand.", sourceObjective = "Sammelt 24 Brisenschreiterhörner von Brisenschreitertalbuks.", progress = "Dieser dummdreiste Fremde glaubt doch wirklich, er kann einfach hier auftauchen und mich in meinem eigenen Land übertreffen?!\n\nOh... Tut mir leid, Kommandant. Das gilt natürlich nicht für Euch.", completion = "Vierundzwanzig also? Gute Arbeit.\n\nIch habe fünfzig mitgebracht.\n\nIch werde jemanden schicken, um das Fleisch abzuholen. Wir wollen ja nichts verkommen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35377] = { id = 35377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jemandem fehlt eine Axt", description = "<Eine Wurfaxt der Frostwölfe steckt in der Flanke dieses Talbuks. Vielleicht hat ja Pirscherin Ogka Interesse an Eurem Fund.>", sourceObjective = "Bringt die Frostwolfaxt zu Pirscherin Ogka in Wor'var.\n\nBereitgestellter Gegenstand:", completion = "Das ist MEINE Axt! Wo habt Ihr die her?", sourceObjectiveStatus = "unverified-source-field" }
quests[35378] = { id = 35378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König der Brisenschreiter", description = "Lasst mich raten: Sie steckte in der Flanke eines Talbuks?\n\n<Ogka wirkt für einen Moment gedankenversunken.>\n\nMit dieser Axt wollte ich Hochrücken, den König der Brisenschreiter, erlegen. Aber gerade als ich sie warf, ist der Talbuk, den Ihr erlegt habt, in die Wurfbahn gesprungen.\n\nIch schlage vor, dass Ihr Jagd auf den König macht. Als ich hinter ihm her war, schien er den Teich bei den Einsamen Fällen im Süden aufsuchen zu wollen.", sourceObjective = "Besorgt Hochrückens Schweif.", progress = "Wie läuft die Jagd auf Hochrücken?", completion = "Gut gemacht, {name}. Ihr habt vollbracht, was mir nicht gelungen ist.\n\nVielleicht seid Ihr Fremden doch keine so schlechten Jäger.", sourceObjectiveStatus = "unverified-source-field" }
quests[35379] = { id = 35379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hemets Schlaraffenland" }
quests[35380] = { id = 35380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweiter Befehlshaber", description = "Wartet... Ich erinnere mich noch an etwas.\n\nSir Edward... Er hat gerufen... Er hat jemanden gesucht.\n\nIch... Ich weiß nicht mehr, wen. Da waren so viele Schreie...", sourceObjective = "Sprecht mit Sir Edward in der Garnison von Admiral Taylor.", completion = "An jedem anderen Tag hätte ich Euch vor das Kriegsgericht gebracht, weil Ihr keine Uniform tragt.", sourceObjectiveStatus = "unverified-source-field" }
quests[35381] = { id = 35381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Schattenmondschatz 5" }
quests[35382] = { id = 35382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Schattenmondschatz 6" }
quests[35383] = { id = 35383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Schattenmondschatz 7" }
quests[35384] = { id = 35384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Schattenmondschatz 8" }
quests[35386] = { id = 35386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung durch den Kriegshymnenklan", description = "<Die Angriffspläne sind mit dicker, schwarzer Tinte auf das Pergament gekritzelt, das in grobes Leder gebunden ist.>\n\nAn alle vorgeschobenen Stellungen:\n\nDer Kriegsherr hat befohlen, dass sich die gesamte Vorhut auf einen Großangriff auf die Invasoren der Allianz in unserem Land vorbereitet. Mehrere der entfernt gelegenen Außenposten der Vorhut haben Angriffspläne erhalten.\n\nBlut und Ruhm sollen unser sein, wenn wir die Eindringlinge der Allianz unter unseren Füßen zerstampfen!\n\nDer Kriegsherr befiehlt und der Kriegshymnenklan folgt! Lok'tar ogar!", sourceObjective = "Stehlt die Angriffspläne des Kriegshymnenklans.", progress = "Was habt Ihr für mich?", completion = "<Hauptmann Washburn schaut sich die Angriffspläne genau an, indem er angestrengt auf die Buchstaben starrt und die Seiten verkehrt herum hält.>\n\nHm... Verstehe... Ja... genau!\n\nWie Ihr schon sagtet, sind dies offensichtlich Angriffspläne. Aber sie wurden wahrscheinlich von Koboldpyromanten verfasst.\n\nEigentlich seltsam, denn ich habe seit meiner Zeit in Azeroth keine Koboldpyromanten mehr zu Gesicht bekommen. Wie auch immer! Ich kann Euch versichern, dass der Außenposten gut bewaffnet und größtenteils feuerfest ist!\n\nSollte man uns angreifen, wird der Außenposten nicht fallen. Das schwöre ich Euch, Kommandant!", sourceObjectiveStatus = "unverified-source-field" }
quests[35387] = { id = 35387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch den Nether", description = "Die Rituale wurden unterbrochen, doch noch immer fließt dunkle Energie in die Nethersignale an den Schauplätzen der Rituale. Dies kann nur heißen, dass die Leuchtfeuer aus dem Wirbelnden Nether selbst gespeist werden.\n\nDer einzige Weg, den Fluss der Leerenenergie zu den Signalen zu unterbrechen, wäre, selbst in den Wirbelnden Nether zu reisen und den ominösen Mächten dort Einhalt zu gebieten!\n\nBenutzt ein Signal, um in den Wirbelnden Nether zu reisen. Einmal dort angekommen, verwendet den Schamanenstein, den die Zorne uns gegeben haben, um mich zu kontaktieren.\n\nDas Licht sei mit Euch.", sourceObjective = "Reist in den Wirbelnden Nether.", sourceObjectiveStatus = "unverified-source-field" }
quests[35388] = { id = 35388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Vormarsch der Leere", description = "Hundertschaften an Leerenschrecken marschieren gen Oshu'gun und bieten sich dem Leerenfürsten Invalidus als Opfergaben dar.\n\nMit jedem ihrer ausgehauchten Leben gewinnt Invalidus weiter an Stärke. Es ist fast so, als dienten die niederen Kreaturen zu nichts anderem, als den Leerenfürsten zu nähren.\n\nWir müssen verhindern, dass Invalidus so mächtig wird, dass er nicht mehr aufzuhalten ist.\n\nTötet so viele Leerenkreaturen wie Ihr könnt. Ich werde währenddessen nach einem Weg suchen, Invalidus aufzuhalten, bevor es zu spät ist.", sourceObjective = "Vernichtet 12 Leerenkreaturen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35389] = { id = 35389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rufunterbrechung", description = "Die Schamanen des Kriegshymnenklans nutzen die Elemente, um dunkle Energie aus der Leere zu kanalisieren.\n\nIch bin kein Schamane, doch weiß sogar ich, dass die meisten Orcklans solche Praktiken verabscheuen. Die Macht der Leere steht gegen das Licht und ist eine Quelle der Entropie und der Zerstörung.\n\nDiese Rituale belasten den Schleier zwischen unserer Welt und dem Wirbelnden Nether. Sollten die Rituale fortgesetzt werden, wird dieses Land bald von Bewohnern des Wirbelnden Nethers überrannt.\n\nTötet die Schamanen, die diese Rituale durchführen, bevor die Vernichtung über uns kommt!", sourceObjective = "Tötet die Ritualanführer des Kriegshymnenklans.", sourceObjectiveStatus = "unverified-source-field" }
quests[35390] = { id = 35390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten über Oshu'gun", description = "Der Leerenfürst Invalidus steht auf dem Gipfel von Oshu'gun und verschlingt die Seelen der Toten.\n\nSogar die gefallen Leerenschrecken, die Ihr vernichtet habt, dienen dem Monster als Nahrung.\n\nWenn wir jetzt nicht handeln, wird Invalidus zu mächtig werden, um von einem Einzelnen besiegt werden zu können.\n\nAn jeder Ritualstätte im Wirbelnden Nether gibt es einen mit den Mächten der Leere angefüllten Kristall. Stört Ihr den Leerenkristall, wird Invalidus Eure Anwesenheit spüren.\n\nSeid auf der Hut. Invalidus sofort versuchen, Eure Seele zu verschlingen.", sourceObjective = "Beschwört und besiegt Invalidus.", sourceObjectiveStatus = "unverified-source-field" }
quests[35391] = { id = 35391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterbrechung der Rituale", description = "Unter dem Oshu'gun führt der Kriegshymnenklan seine dunklen Rituale durch.\n\nDie Schamanen des Kriegshymnenklans möchten ihren Klan stärken, indem sie eine große Quelle Leerenenergie im Herzen des Oshu'gun anzapfen.\n\nObwohl ich nicht sicher weiß, was die Quelle dieser Macht ist... befürchte ich, dass der sterbende Naaru K'ure etwas damit zu tun haben könnte.\n\nDie Rituale des Kriegshymnenklans müssen aufhören, oder der Schleier, der diese Welt vom Wirbelnden Nether trennt, wird reißen.\n\nSucht die Ritualtotems, die bei der Kanalisierung dieser Rituale verwendet werden, und zerstört sie.", sourceObjective = "Zerstört die Ritualtotems.", sourceObjectiveStatus = "unverified-source-field" }
quests[35392] = { id = 35392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Nether rückt näher", description = "Der Kriegshymnenklan hat die Macht der Leere angezapft und damit den Schleier, der unsere Welt vom Wirbelnden Nether trennt, geschwächt.\n\nIm Nether öffnen sich Portale, die drohen, die Schrecken der Leere nach Draenor zu bringen.\n\nSollten sich diese Portale vollends öffnen, ist der Weg für alle möglichen Dämonen und Leerenkreaturen frei, die dann in ganz Nagrand wüten werden.\n\nGeht und bringt die Portale zum Einsturz, bevor sie ihr volles Potenzial entfalten.", sourceObjective = "Bringt 10 Leerenportale zum Einsturz.", sourceObjectiveStatus = "unverified-source-field" }
quests[35393] = { id = 35393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterangelegenheiten", description = "Die Geister der Toten werden schon seit Langem vom Berg Oshu'gun angezogen.\n\nSo lange ich mich erinnern kann, führt die gespenstische Pilgerfahrt die Geister der Urahnen auf ihrem Weg in das Innere des Berges durch den Wald. Ich fürchte, dass die Seelen, die es zum Oshu'gun zieht, von der wachsenden Leere im Inneren des Berges verzehrt werden.\n\nBegebt Euch zum Ahnengrund und nehmt Kontakt zu den Geistern auf. Findet heraus, was dort vor sich geht.", sourceObjective = "Sprecht mit den Geistern beim Ahnengrund.", completion = "Die Lage hier ist düster, {name}. Aber ich habe gefühlt, dass wir uns wiedersehen würden.\n\nIch kann den Ruf der Leere nicht so laut vernehmen wie die anderen, weil ich noch nicht so lange tot bin und mein Körper weit von diesem Ort entfernt ruht.\n\nAber das wird sich mit der Zeit ändern.\n\nWenn Ihr helfen wollt, dann hört gut zu. Denn es bleibt nicht mehr viel Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[35395] = { id = 35395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal Gordawgs", description = "Die riesige Kreatur, die zwischen uns und der inneren Kammer steht, ist der große Zorn, den wir zum Thron der Elemente zurückbringen wollten.\n\nGordawg ist jetzt gefesselt. Er ist ein Sklave Cho'galls. Mein Herz wird dabei schwer vor Trauer, eine solch großartige Kreatur als willenlosen Sklaven des Bösen sehen zu müssen.\n\nJetzt gibt es kein Zurück mehr. Um weiterzukommen, müssen wir an Gordawg vorbei.\n\nAuch wenn es mich schmerzt: Gordawg muss sterben.\n\nTötet Gordawg und bringt das Herz des Zorns zurück zum Thron der Elemente, dorthin, wo es hingehört.", sourceObjective = "Beschafft das Herz des Zorns.", progress = "Was ist mit Gordawg? Hat der große Zorn endlich seine Ruhe gefunden?", completion = "Gordawg war ein mächtiger Verbündeter. Die Elemente werden den Verlust des Zorns betrauern, aber sein Tod war die einzige Lösung. Gordawg hätte nicht ein Sklave des Bösen bleiben wollen.\n\nGordawg weilt zwar nicht mehr unter uns, doch ist das Herz eines Zorns ewig und unzerbrechlich. Eines Tages wird dieses leuchtende Herz in einem neuen Erdzorn Gestalt annehmen.\n\nSo ist der Lauf des Lebens auf dem Elementarplateau.", sourceObjectiveStatus = "unverified-source-field" }
quests[35396] = { id = 35396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das dunkle Herz des Oshu'gun", description = "Inmitten des verwitterten Wracks der Genedar befindet sich der Eingang zur inneren Kammer des Schiffes. Dort scheint die Leerenenergie am stärksten zu sein.\n\nIhr müsst die innere Kammer betreten und Euch dem Bösen darin stellen. Die Vorstellung des schrecklichen Schicksals des großen Naarus K'ure ist wahrhaft traurig, aber dennoch muss das Böse dort drinnen ausgelöscht werden.\n\nMöge das Licht mit Euch sein, {name}.", sourceObjective = "Betretet das Sanktum des Naaru.", completion = "Das Schicksal von K'ure war nicht abwendbar.\n\nCho'gall hat die Verwandlung des Naaru in einen Leerengott vorangetrieben, um ganz Draenor zu vernichten. Cho'gall muss seine Strafe bekommen. Aber jetzt wollen wir zunächst das Andenken des großen Naaru K'ure ehren.\n\nK'ure war wahrlich der Retter meines Volkes, ein Freund der Rechtschaffenen und der Lehrer der Propheten.\n\nMöge der große Naaru ewig in unseren Herzen weiterleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[35397] = { id = 35397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die fahle Bedrohung", description = "Wenn wir Cho'gall davon abhalten wollen, den Naaru zu vernichten, müssen wir uns einen Weg durch die Fahlen Tiefen schlagen: eine finstere, verwinkelte Höhle, in der es von Fahlen nur so wimmelt.\n\nDie Fahlen sind gefallene Orcs, die alles verachten, was gut und heilig ist. Je länger sie unter der Erde ungestört bleiben, desto weiter reifen ihre dunklen Pläne.\n\nBegebt Euch in die Fahlen Tiefen, erschlagt die widerlichen Kreaturen im Innern und macht kurzen Prozess mit ihrem Anführer, Grauseher.", sourceObjective = "Tötet Grauseher und 6 fahle Orcs.", completion = "Die Fahlen sind elende Wesen, die das Licht hassen und Pläne gegen die Unschuldigen schmieden. Ohne Grauseher als ihren Anführer werden sie jede Organisation verlieren und schon bald ins Chaos stürzen.\n\nSollte aus ihren Reihen ein neuer Anführer aufsteigen, werden wir erneut mit voller Kraft zuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35398] = { id = 35398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Bindung", description = "Just in diesem Moment machen die Fahlen eine Armee von Elementaren in der Schattenfallschlucht zu ihren Sklaven. Viele von ihnen befinden sich bereits in Gefangenschaft und wenn wir ihnen nicht zu Hilfe eilen, werden noch viele weitere folgen.\n\nBegebt Euch zur Schattenfallschlucht und befreit die Elementargeister, die noch nicht vollkommen von den Fahlen in Besitz genommen worden sind. Was die anderen betrifft, die bereits vollends zu Sklaven geworden sind: Die einzige Gnade, die wir ihnen jetzt noch gewähren können, ist ein schneller Tod.", sourceObjective = "Befreit 8 Elementargeister.", progress = "Die Elementargeister dürfen nicht in die Hände der Fahlen fallen!", completion = "Beim Befreien der Elementargeister von ihren Fesseln habt Ihr ganze Arbeit geleistet. Wenn Cho'gall und die Fahlen eine Armee von Elementarsklaven wollen, dürfen sie sie nicht bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35399] = { id = 35399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Kompost der Geschichte", description = "Eure Wolfskönigin lässt mich nicht aus den Augen.\n\nDie Kinder der Magnaron mögen mein Dorf zerstört haben, aber es waren die Kinder der Genesaurier, die meine Leute entführt haben.\n\nDie Botani und ihre Helfer haben unsere Leute in den Klingenflor verschleppt. Und wenn wir sie wiedersehen, sind sie nicht mehr dieselben.\n\nIhr habt den Schädeln schon einmal geholfen. Ich bitte Euch erneut um Hilfe.\n\nDringt in den Klingenflor ein und sucht nach meinen vor Kurzem verschleppten Leuten.\n\nVielleicht sind sie ja sogar noch am Leben.", sourceObjective = "Sucht nach Torg Ohrensammler, Meka der Gesichtsfresserin und Chag dem Nasenlosen im Klingenflor.", completion = "Tot? Alle tot? Tot und zu Mulch verarbeitet und vergessen. Kein Chag mit seiner fehlenden Nase, keine Meka mit ihrer Vorliebe für Gesichter.\n\nUnd Torg, mein geliebter Torg. Unser gemeinsamer Sohn. Ein Sohn, der immer noch vermisst wird.\n\nDie Botani werden dafür bezahlen. Sie werden für ihre Taten brennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35400] = { id = 35400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Befallenen", description = "Ich habe Verständnis für Kaz' Wunsch, ihr Volk zu retten, doch ihr Plan ist unbesonnen, und sie hat uns nicht alles erzählt.\n\nIch bin hierher gekommen, um sicherzustellen, dass sich ihre Pläne nicht gegen uns richten. Und jetzt muss ich diesen... diesen... Horror sehen.\n\nWas haben die Botani diesen Orcs angetan?\n\nDiese befallenen Seelen müssen erlöst werden. Schenkt ihnen Frieden.", sourceObjective = "Tötet 6 befallene Orcs.", completion = "Ich hatte nicht damit gerechnet, auf solche... Kreaturen zu stoßen. Ich wusste immer, dass Gorgrond ein gefährlicher Ort ist, aber so teuflisch hatte ich es mir nicht vorgestellt.\n\nDanke, dass Ihr Euch erbarmt habt, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[35401] = { id = 35401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vortex Pinnacle Reward Quest" }
quests[35402] = { id = 35402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stimme Iyus", description = "Die Gier der Botani und ihrer widerlichen Diener kennt keine Grenzen.\n\nSie wollen Nahrung, sie nehmen sich unser Land. Sie wollen eine Armee, sie nehmen sich unsere Leute.\n\nEs wird Zeit, die holzigen Herzen dieser Pflanzenwesen mit Furcht zu erfüllen.\n\nSucht nach ihrem Anführer – der Stimme Iyus. Er ist ein Botani, der im Namen ihres Genesauriermeisters spricht.\n\nTötet ihren geliebten Anführer direkt in der Sicherheit seines kostbaren Flors.", sourceObjective = "Tötet die Stimme Iyus.", completion = "Es reicht nicht aus, die Botani einfach nur zu töten. Sie werden immer in der Überzahl bleiben.\n\nMan muss sie hart und nachhaltig treffen, dort, wo es am meisten wehtut.\n\nZum Beispiel, indem man ihren heiligsten Anführer zur Strecke bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[35403] = { id = 35403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vortex Pinnacle Reward Quest" }
quests[35404] = { id = 35404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grim Batol Reward Quest" }
quests[35405] = { id = 35405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grim Batol Reward Quest" }
quests[35406] = { id = 35406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supersamen", description = "Diese Samen wurden von den Botani mit größter Sorgfalt beschützt.\n\nDie kleinen Lebenskapseln strahlen eine große Kraft aus.\n\nSie könnten sich noch als nützlich erweisen.", sourceObjective = "Sammelt angereicherte Samen.", progress = "Was habt Ihr gefunden?", completion = "Samen. Sie sehen so schlicht aus, doch jeder davon birgt das Potenzial unbeschreiblicher Zerstörung. Ganz wie mein Sohn.\n\nEs war klug von Euch, sie mitzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35407] = { id = 35407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesstrafe", description = "Verräter, allesamt!\n\nWas Ihr hier seht, sind die letzten Überbleibsel von Truppen, die Admiral Taylor und der Allianz treu ergeben sind.\n\nIch werde nicht zulassen, dass diese Verräter ungestraft davonkommen.\n\nIhr seht aus, als wärt Ihr bereit für diese Aufgabe. Zeigt ihnen, wie man mit ihresgleichen in Kriegszeiten verfährt.", sourceObjective = "Tötet 8 Garnisonsverräter.", completion = "Gut gekämpft. Für die Allianz!", sourceObjectiveStatus = "unverified-source-field" }
quests[35408] = { id = 35408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ladet die Kanonen", description = "Unsere Waffenvorräte wurden von den Verrätern geplündert. Wir haben nur noch ein paar Kanonen ohne Munition.\n\nIch will, dass ihr ein paar Kanonenkugeln zusammensammelt, damit wir sie wieder in Betrieb nehmen können.\n\nUnd eine weitere Kanone wäre auch nicht schlecht.", sourceObjective = "Holt 10 Arsenalkanonenkugeln und 1 Arsenalkanone zurück.", progress = "Ich hoffe, Ihr habt eine Kanone und ein paar Kugeln dabei.", completion = "Gute Arbeit, Soldat.", sourceObjectiveStatus = "unverified-source-field" }
quests[35411] = { id = 35411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Gurub Reward Quest" }
quests[35412] = { id = 35412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Gurub Bonus Objective Reward Quest" }
quests[35413] = { id = 35413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost City of the Tol'vir Reward Quest" }
