quests[35415] = { id = 35415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Origination Reward Quest" }
quests[35416] = { id = 35416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Genesauriers", description = "Jetzt habt Ihr nicht nur den Willen der Genesaurier, sondern auch genug Wasser und Samen, um eine ganze Armee zu züchten, Kommandant, von den Zwergenleben, die Ihr gerettet habt, ganz zu schweigen.\n\nDie Mission war ein voller Erfolg.\n\nIch werde die Festung weiter auskundschaften und sehen, was wir noch an Material bergen können.\n\nIhr könntet währenddessen das Artefakt zurück zu Durotan am Außenposten bringen. Ich werde dort zu Euch stoßen, wenn ich hier fertig bin.", sourceObjective = "Sprecht mit Durotan in der Wildwacht in Gorgrond.", completion = "Gute Arbeit, Kommandant. Viele Orcs haben versucht, sich die Macht des Genesauriers zu eigen zu machen, doch noch nie waren diese Bemühungen von Erfolg gekrönt.\n\nIhr habt uns eine mächtige Waffe für unseren nächsten Kampf gegen die Eiserne Horde verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[35420] = { id = 35420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonusbelohnung - Hallen des Ursprungs" }
quests[35424] = { id = 35424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Origination Reward Quest" }
quests[35426] = { id = 35426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonusbelohnung - Hallen des Ursprungs" }
quests[35429] = { id = 35429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pollenpotenzial!", description = "Diejenigen von uns, die in Gorgrond aufwuchsen, haben schon früh ein paar Geheimnisse der Botani gelernt, die uns helfen, unsere eigenen Pflanzen zu züchten.\n\nHunger kennen wir aus diesem Grund bei den Lachenden Schädeln kaum.\n\nDie Verheerer sind der Schlüssel.\n\nIn der Umgebung der Immermornquellen findet ihr Verheerer aller Art. Tötet sie und bringt mir die Pollen, die sie mit sich führen. Dann kann ich sie zum Nutzen der Garnison kultivieren.", sourceObjective = "Sammelt 20 starke Pollen.", progress = "Nur wenige wagen es, die Botani beim Anbau von Pflanzen herauszufordern.", completion = "Ah... Ja, ja, ja. Frische Pollen. Mit einer Prise geheimer Zutaten lässt sich daraus genug Nahrung für eine ganze Armee züchten. Natürlich nur, wenn man sich mit den geheimen Künsten auskennt.", sourceObjectiveStatus = "unverified-source-field" }
quests[35430] = { id = 35430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlitzer", description = "Ihr habt eine Menge Lachende Schädel gefunden. Alle Freunde, Angehörige... alle tot. Ihr habt jedoch nicht meinen lieben Schlitzer gefunden.\n\nWenn Ihr Euch in die Immermornquellen einschleicht, haltet nach meinem Schlitzer Ausschau. Sucht ihn und rettet ihn.\n\nEr ist ein guter Junge, und er verdient einen besseren Tod, als befallen zu werden.\n\nIch werde ein paar Verheerer versammeln und den Ort aus der Luft angreifen. Sucht mich in Immermorn auf, falls Ihr Schlitzer vor mir findet.", sourceObjective = "Findet Schlitzer.", completion = "Die Botani haben meinen Vater entführt. Und meine Freunde. Und jetzt zwingen sie mich, Obst zu essen!\n\nWie können sie nur so grausam sein?!\n\nHabt Ihr sie alle erledigt?\n\nBitte, Ihr müsst sie töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[35431] = { id = 35431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das beste Gift", sourceObjective = "Sammelt 8 Häscherranken.", sourceObjectiveStatus = "unverified-source-field" }
quests[35432] = { id = 35432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buschräuber", description = "Kaz benutzt uns nur, das weiß ich. Sie gehört den Lachenden Schädeln an, wir dürfen ihr NICHT trauen.\n\nVorläufig bin ich bereit, ihr kleines Spielchen mitzumachen, bis wir mehr erfahren. \n\nKaz wird Euch bitten, Euch zu den Immermornquellen zu begeben. Ich schlage vor, dass Ihr dort alle Botani tötet, auf die Ihr stoßt.\n\nWenn es Euch gelingt, einen Großteil dieser fürchterlichen Tauregner auszumerzen, bewahrt Ihr möglicherweise zukünftige Orcs davor, befallen zu werden.\n\nIch werde bei Kaz bleiben und sie nicht aus den Augen lassen.", sourceObjective = "Tötet 7 Blütenweber.", completion = "Ich dachte, die Lachenden Schädel führten etwas im Schilde. Jetzt verstehe ich langsam.\n\nSie setzen der Grausamkeit der Botani ihre eigene Grausamkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35433] = { id = 35433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abholzung", description = "Sie entführen Kinder? Kinder?!\n\nHättet Ihr Kaz' Sohn nicht gerettet, wäre er zu Mulch verarbeitet worden, genau wie die anderen.\n\nIhr solltet ihnen eine Nachricht schicken, die sie verstehen. Zerlegt ihre großen Tauregner. Reißt sie auseinander.\n\nLasst sie wissen, dass es ein Fehler ist, uns unsere Kinder zu nehmen.", sourceObjective = "Tötet 3 Taumeister.", completion = "Sie haben Glück gehabt, dass Ihr es wart, der sie getötet hat. Ich hätte versucht, Bilder in ihre toten Holzkörper zu schnitzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35434] = { id = 35434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Quelle des Lebens", description = "Es klingt so, als hätten diese... \"Zwerge\", die Ihr gefunden habt, ein mächtiges Artefakt der Botani gestohlen.\n\nAber die Narren hatten keine Ahnung, dass es nur mit einem speziellen Wasser funktioniert.\n\nIm Norden an den Klippen der Immermornhöhe gibt es einen Brunnen.\n\nDort findet Ihr einen Wächter – eine Kreatur des Wassers, die wir Utrophis nennen.\n\nVernichtet Utrophis und nehmt seine Essenz an Euch. Dann kommt Ihr der Macht der Botani und ihres Genesauriers ein ganzes Stück näher.", sourceObjective = "Schöpft Wasser von Utrophis.", progress = "Jahrelang hat der Lachende Schädel das heilige Wasser unangetastet gelassen. Wir haben den Zorn der Botani gefürchtet. Wir hätten sie schon vor langer Zeit in Brand setzen sollen.", completion = "Wasser von Utrophis. Ich habe es zwar noch nie in Händen gehalten, gerochen oder gekostet, aber schon viele Geschichten darüber gehört, viele Legenden.\n\nIrgendwie hatte ich es mir spektakulärer vorgestellt.", sourceObjectiveStatus = "unverified-source-field" }
