quests[35443] = { id = 35443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Aman Reward Quest" }
quests[35444] = { id = 35444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Südliche Wildnis", description = "Erst die Eiserne Horde, dann die Schattenmondorcs und jetzt auch noch Ärger im Süden!\n\nMein Bruder ist einer der Feenreiter im Süden, beim Draakorium.\n\nEr sagt, dass Kreaturen aus dem Sumpf das Land überrennen. Was passiert mit dieser Welt?\n\nIhr seht auf jeden Fall wie <ein kampferprobter Abenteurer/eine kampferprobte Abenteurerin> aus. Würdet Ihr die Lage für mich erkunden, wenn Ihr dorthin unterwegs seid?", sourceObjective = "Sprecht mit Prälat Reenu beim Draakorium.", completion = "Danke, dass Ihr uns zur Hilfe gekommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[35446] = { id = 35446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Oculus Reward Quest" }
