quests[35448] = { id = 35448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Dunkelmeister Go'vid" }
quests[35449] = { id = 35449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Utgarde Pinnacle Reward Quest" }
quests[35450] = { id = 35450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Südliche Wildnis", description = "Ich habe beängstigende Nachrichten von unseren Freunden im Draakorium südlich von hier erhalten.\n\nDer Ort liegt nahe eines Sumpfes und vor Kurzem sind in seinen Außenbezirken gefährliche Kreaturen gesichtet worden.\n\nIhr seht auf jeden Fall wie <ein kampferprobter Abenteurer/eine kampferprobte Abenteurerin> aus. Würdet Ihr Euch für mich nach unseren Leuten dort erkunden, wenn Ihr dorthin unterwegs seid?\n\nIch möchte sichergehen, dass es ihnen gut geht.", sourceObjective = "Sprecht mit Prälat Reenu beim Draakorium.", completion = "Ah, Prälatin Luari hat Euch geschickt, oder? Sie ist so eine nette Frau und kümmert sich immer um alle.", sourceObjectiveStatus = "unverified-source-field" }
quests[35452] = { id = 35452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonuszielbelohnung: Turm Utgarde" }
