quests[35458] = { id = 35458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Lightning Reward Quest" }
quests[35459] = { id = 35459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Südliche Wildnis", description = "Von: Prälat Reenu\n\nEdle Freunde der Allianz, die Draenei des Draakoriums heißen Euch in Frieden willkommen.\n\nDas Draakorium wurde von Feinden aus dem nahe gelegenen Sumpf angegriffen.\n\nVor Kurzem ist hier eine Karawane aus Azeroth durchgezogen und hat sich wohl auf gefährliches Territorium vorgewagt.\n\nAlle erfahrenen Abenteurer, die uns helfen wollen, werden gebührend belohnt.", sourceObjective = "Sprecht mit Prälat Reenu beim Draakorium.", sourceObjectiveStatus = "unverified-source-field" }
quests[35460] = { id = 35460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff der Eisernen Horde", description = "Es wird berichtet, dass sich das Dunkle Portal vor dem Angriff rot färbte. Sie nennen sich die Eiserne Horde, aber sie scheinen nichts mit der Horde, die wir kennen, zu tun zu haben.\n\nIhre Armee ist extrem gut ausgerüstet und es scheint unendlich viele von ihnen zu geben.\n\nSie haben bereits Burg Nethergarde eingenommen. Unsere Truppen an der Front könnten Eure Hilfe gebrauchen, {class}.", sourceObjective = "Tötet 8 Grunzer des Eisernen Marsches.", completion = "Ihr seid gut in Form, Champion. Eure Anwesenheit auf dem Schlachtfeld hat die Truppen bestimmt motiviert.", sourceObjectiveStatus = "unverified-source-field" }
quests[35461] = { id = 35461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege of Niuzao Reward Quest" }
quests[35462] = { id = 35462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagert", description = "Unsere Truppen haben den Kanonen der Eisernen Horde nichts entgegenzusetzen. Ich weiß nicht, wie lange wir das noch durchhalten. Unsere Streitkräfte sind bereits zu stark dezimiert worden.\n\nWir müssen diese Kriegsmaschinen irgendwie aufhalten.", sourceObjective = "Sabotiert 3 Verwüster der Eisernen Horde.", completion = "Die Eiserne Horde wird eine Weile brauchen, um diese Verwüster zu reparieren. Throm-Ka, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[35463] = { id = 35463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subversive Späher", description = "Wir konnten einen Großteil unserer Schlachtpläne nicht umsetzen. Wir werden garantiert beobachtet.\n\nDie Eiserne Horde setzt wohl überall in den Verwüsteten Landen Späher ein. Der Sieg entgleitet uns.", sourceObjective = "Tötet 5 Eiserne Späher.", completion = "Ihr habt wie viele Späher getötet? Kein Wunder, dass wir unsere Pläne nicht umsetzen konnten...", sourceObjectiveStatus = "unverified-source-field" }
quests[35464] = { id = 35464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ende der Hinrichtungen", description = "Wir sind so schnell gekommen, wie es ging... aber wir sind zu spät. Nethergarde ist gefallen. Die Eiserne Horde hat einige der Krieger von Nethergarde gefangen genommen.\n\nSie versuchen bestimmt, aus unseren Truppen wichtige Informationen herauszupressen.\n\nWenn die Verhöre beendet sind, werden sie ihre Gefangenen bestimmt hinrichten. Die Zeit läuft uns davon.", sourceObjective = "Tötet 3 Scharfrichterinnen des Eisernen Marsches.", completion = "Die Gefangenen sind zwar mitgenommen, aber frei. Ihre Familien stehen in Eurer Schuld, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[35465] = { id = 35465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Stone Reward Quest" }
