quests[35481] = { id = 35481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Nizzix" }
quests[35482] = { id = 35482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Admiral Taylor", description = "Admiral Taylor wusste, wer hinter all dem steckte. Er wies uns an, jeden zu retten, den wir retten können... Er wollte die Dinge selbst in die Hand nehmen.\n\nWir haben nie wieder von ihm gehört, aber wir haben unsere Befehle.\n\nBitte... findet ihn. Er ging in Richtung des Bauernhofs.", sourceObjective = "Findet Admiral Taylor auf Admiral Taylors Bauernhof.", completion = "Von Kommandant zu Kommandant... Danke.\n\nWir haben so viel gemeinsam durchgemacht, nicht wahr, {name}? Vashj'ir... der Jadewald... die Löwenlandung...\n\nEs ist mir wirklich eine Ehre, meine Reise an Eurer Seite beenden zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35483] = { id = 35483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drak'Tharon Keep Reward Quest" }
quests[35484] = { id = 35484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drak'Tharon Keep Reward Quest" }
quests[35486] = { id = 35486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahnsinnige Leutnants", description = "Wir sollten mehr über unseren neuen Feind erfahren.\n\nUnsere Späher haben einige Leutnants der Eisernen Horde identifiziert. Ihr Angriff ist so gut organisiert, dass er nicht nur auf Stammeswissen beruhen kann. Ihre Leutnants haben sicherlich Zugang zu geheimen Schlachtplänen.\n\nIhr seid <der einzige Soldat, dem/die einzige Soldatin> der; ich diese Mission anvertrauen kann, {name}.", sourceObjective = "Beschafft Schlachtpläne der Eisernen Horde.", progress = "Konntet Ihr irgendwelche Schlachtpläne ausfindig machen?", completion = "Sehen wir uns diese Schlachtpläne mal an.", sourceObjectiveStatus = "unverified-source-field" }
quests[35487] = { id = 35487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerbestattung", description = "Ich habe da jede Menge Leichen gesehen. Kaz hat immer gesagt, man muss die Leichen verbrennen.\n\nDann können sie auch nicht als gemeine Grüne zurückkommen.\n\nWir sollten die Leichen verbrennen.", sourceObjective = "Verbrennt 6 Leichen.", completion = "Das hat ganz schön gestunken.", sourceObjectiveStatus = "unverified-source-field" }
quests[35488] = { id = 35488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Schreckensfelsogern", description = "Die Dummheit der Schreckensfelsoger überrascht mich immer wieder. Die Eiserne Horde benutzt sie offensichtlich, um ihre eigenen düsteren Ziele voranzutreiben.\n\nTrotzdem müssen wir den Ogern zeigen, was passiert, wenn man sich der Allianz widersetzt. Es wird Zeit, diesen Schreckensfelsogern eine Lektion zu erteilen.", sourceObjective = "Tötet 8 Schreckensfelsoger.", completion = "Es ist wichtig, dass unsere Feinde erkennen, was geschieht, wenn man die Allianz angreift. Ich bin froh, dass es Euch gelungen ist, ihnen das zu zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35489] = { id = 35489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahn'kahet: The Old Kingdom Reward Quest" }
quests[35490] = { id = 35490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahn'kahet: The Old Kingdom Reward Quest" }
quests[35491] = { id = 35491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suchmarkierung: Unterseher Blutmähne Vignette" }
quests[35492] = { id = 35492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Nethergarde!", description = "Die Eiserne Horde kontrolliert Burg Nethergarde, aber sie sind Trottel, wenn sie glauben, wir würden unser Land nicht zurückfordern.\n\nUnsere Truppen lechzen danach, das Blut dieser Wilden zu vergießen, aber wir brauchen einen Champion wie Euch, der sie in die Schlacht führt.", sourceObjective = "Platziert die Flaggen der Allianz in Burg Nethergarde.", completion = "Die Eiserne Horde wird uns bald fürchten, so wie sie sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[35493] = { id = 35493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahn'kahet: Das Alte Königreich - Bonusbelohnung" }
quests[35494] = { id = 35494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andenken an die Gefallenen", description = "Es waren so viele. Die Wachen konnten sie nicht aufhalten... niemand konnte sie aufhalten. So vielen Seelen haben diese Wilden die Körper genommen.\n\nWir dürfen die, die ihr Leben hingaben, um Nethergarde zu verteidigen, niemals vergessen. Wenn Ihr irgendwelche Andenken an die Gefallenen findet, dann bringt sie mir bitte.", sourceObjective = "Besorgt Strumners Schwert, Keris Humpen und Krolans Schild.", progress = "Habt Ihr etwas gefunden?", completion = "Danke, {name}. Diese Andenken werden uns für immer an den Tag erinnern, an dem wir so viele der unseren verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[35495] = { id = 35495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zahnbrecher der Vernichter", description = "Wenn die Schlachtpläne, die Ihr mitgebracht habt, stimmen, dann tragen die Schreckensfelsoger ebenso große Schuld an dieser Verwüstung wie die Eiserne Horde. Es wird Zeit, dass wir diesen Ogern eine Lektion erteilen.\n\nDie Eiserne Horde stützt sich vor allem auf einen großen Oger in Schreckensfels, der sich Zahnbrecher nennt. Sein Tod wird ihre Schlachtpläne durchkreuzen.", sourceObjective = "Tötet Zahnbrecher den Vernichter.", completion = "Zahnbrecher ist tot? Gut. Die Horde wird eine Weile brauchen, um einen anderen Oger zu finden, der schlau genug ist, um ihnen nützlich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[35496] = { id = 35496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enohars Rache", description = "Sie... Sie haben meine Schwester getötet. Diese Bestien marschierten geradewegs durch die vorderen Tore und... Es war furchtbar.\n\nDie Schreckensfelsoger standen beim Angriff an ihrer Seite. Sie alle sollen dafür büßen. Hier, gebt ein paar Tropfen von dem Gift in ihren Ratteneintopf. Das Gift wird langsam ihre Gedärme zersetzen. Ihr Tod wird lang und schmerzhaft sein, so wie sie es verdienen.\n\nBitte, für meine Schwester.", sourceObjective = "Vergiftet die Nahrung der Schreckensfelsoger.", completion = "Ich wünschte, ich könnte ihre Gesichter sehen, wenn sie leiden. Ich hoffe, dass sie einen langsamen und schrecklichen Tod sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[35497] = { id = 35497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azjol-Nerub Reward Quest" }
quests[35498] = { id = 35498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azjol-Nerub Reward Quest" }
quests[35499] = { id = 35499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Türme sprengen" }
quests[35500] = { id = 35500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gar'mak Klingendreher", description = "Dank der Informationen, die Ihr gesammelt habt, wissen wir jetzt, dass der Angriff von Gar'mak Klingendreher, einem mächtigen Orc der Eisernen Horde, angeführt wird. Er hat sich in Burg Okril'lon verschanzt.\n\nSein Tod wird den Krieg nicht beenden, aber die Kommunikation innerhalb der Eisernen Horde unterbrechen. Das wird uns wertvolle Zeit verschaffen, um weitere Streitkräfte zu sammeln und einen Schlachtplan für den Kampf gegen diese neue Bedrohung aufzustellen.", sourceObjective = "Tötet Gar'mak Klingendreher.", completion = "Es war mir eine Ehre, an Eurer Seite zu kämpfen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[35501] = { id = 35501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammnisgeschoss", description = "Bei dieser unheimlich großen Sprengladung scheint es sich um Munition für die Hauptkanone zu handeln, die das Zentrum der Bastion bildet.\n\nDie Ladestelle muss sich auf einer der unteren Etagen befinden, aber die Munition hat es nicht so weit geschafft.", sourceObjective = "Sammelt 4 Verdammnisgeschosse ein.", progress = "Dieser Lader kann mehrere Ladungen Verdammnisgeschosse gleichzeitig aufnehmen.", completion = "Diese Verdammnisgeschosse lassen sich leicht in den Waffenlader legen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35502] = { id = 35502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Utgarde Keep Reward Quest" }
quests[35503] = { id = 35503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Char der Brennende" }
quests[35504] = { id = 35504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joker des Eisens" }
quests[35505] = { id = 35505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisster Holzfäller", description = "Mein Freundin war mit mir in der Maulwurfmaschine. Die gute alte Frenna hat sich immer die Mühe gemacht, ihre Beobachtungen in einem Tagebuch zu notieren.\n\nPenny hier möchte, dass ich Euch sage, wo sie ist. Ich bin mir nicht sicher, aber sie war auf dem Weg nach draußen hinter mir. Ich glaube, sie hat es nicht geschafft.", sourceObjective = "Findet Frenna im Schlingenherz.", completion = "Frenna hat es nicht aus dem Schlingenherz heraus geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[35506] = { id = 35506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holzanbau", description = "Ich habe diesen Zwerg Thuldren gefunden. Kam aus Schlingenherz gerannt wie von der Tarantel gestochen.\n\nFaselte irgendwas von wegen, er habe sich mit seiner Maulwurfmaschine hierhin verirrt und er hätte es nur knapp lebend rausgeschafft. Eine Freundin von ihm, Frenna, sei noch dort.\n\nEr hat aber auch etwas erwähnt, das sich als nützlich erweisen könnte. Anscheinend haben die Kreaturen da drin irgendeinen Saft, der das Wachstum von Dingen beschleunigt.\n\nÜbrigens habe ich vor, nach Thuldrens Maulwurfmaschine zu suchen. Trefft Euch mit mir im Schlingenherz, sobald Ihr fertig seid.", sourceObjective = "Sammelt 100 Portionen des Wachstumssafts für Urtume von den Botani oder Urtumen im Schlingenherz.", progress = "Ihr steht hoffentlich voll im Saft, was?!", completion = "Ihr habt ihn! Ihr solltet diese Maulwurfmaschine für den Weg zurück zu Eurem Außenposten benutzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[35507] = { id = 35507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runter in den Gorenbau", description = "Zwerge sind nicht gerade die Hellsten. Sie müssten doch wissen, dass man, wenn man tief genug gräbt, auf Goren stößt!\n\nWenn Ihr Euch in das eiserne Fort begebt, solltet Ihr besser ein paar Goren abmurksen, sonst fangen sie an, die Wände anzunagen und das ganze Ding stürzt ein.\n\nIch würde das ja selbst übernehmen, aber ich bin noch immer so voll von all dem Obst, das ich essen musste.", sourceObjective = "Tötet 7 Goren in Moiras Bastion.", completion = "Goren gründlich getilgt!", sourceObjectiveStatus = "unverified-source-field" }
quests[35508] = { id = 35508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitel I: Nahrung anpflanzen", description = "Im Schlingenherz gibt es seltsam schimmernde Objekte, die offensichtlich von einer Art stechenden Kreatur befruchtet werden.\n\nDie Botani sammeln manchmal ein, was auch immer diese Kapseln produzieren. Ich weiß nicht genau, worum es sich da handelt, aber es könnte gefährlich für uns sein.\n\n- Frenna", sourceObjective = "Zerstört 8 Sporenkapseln.", completion = "He, gut gemacht, Kommandant!", sourceObjectiveStatus = "unverified-source-field" }
quests[35509] = { id = 35509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wille der Genesaurier", description = "Ich bin mir ziemlich sicher, dass die Zwerge das Artefakt in das eiserne Fort dort gebracht haben.\n\nKönnt Ihr es ihnen wieder abnehmen?", sourceObjective = "Bergt den Willen der Genesaurier.", progress = "Kaz sagte, ich solle mich für diesen Kampf verstecken.", completion = "Der Genesaurier ist auf dem Weg hierher!", sourceObjectiveStatus = "unverified-source-field" }
quests[35510] = { id = 35510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iyu", description = "Wir werden von einem Genesaurier angegriffen!\n\nEr fordert das Artefakt zurück.\n\nKaz und Draka bekämpfen ihn gerade an der Oberfläche, aber sie werden Euch brauchen. Draka sagte, ich könnte das große Geschütz abfeuern. Also werde ich hierbleiben, um genau das zu tun.", sourceObjective = "Besiegt Iyu.", completion = "Es war mir eine große Ehre, heute an Eurer Seite kämpfen zu dürfen, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[35511] = { id = 35511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaz die Kreischende", sourceObjective = "Kommandant, Ihr reist umher und tötet alle, die sich Euch in den Weg stellen.\n\nDas klingt nach Spaß.\n\nIch möchte mich gerne... Euren \"Anhängern\" anschließen... wie die Wolfsdame sie immer wieder nennt.\n\nMein Zuhause ist vernichtet, meine Familie ist zu Kompost verarbeitet worden und dieser Ort hat jeden Reiz verloren.\n\nErlaubt mir, mich Euch anzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
