quests[35523] = { id = 35523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Morva Seelenzerstörer" }
quests[35524] = { id = 35524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitel III: Ritual der Verkohlten", description = "Ich habe ein seltsames Ritual der Urtume beobachten können. Sie treten in ein Feuer, brennen sich die Blätter von ihren Ästen und verkohlen so ihre Rinde.\n\nIch nenne es das \"Ritual der Verkohlten\". Wenn wir die Urtume schwächen wollen, können wir sie loswerden, bevor sie noch stärker werden.\n\n- Frenna", sourceObjective = "Tötet 4 Urtume.", completion = "Ihr habt gesehen, wie sie sich selbst die Blätter abgebrannt haben? Das ist ja so, als würde ich mir meine zuckersüßen Zöpfe abschneiden!", sourceObjectiveStatus = "unverified-source-field" }
quests[35525] = { id = 35525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Botanica Reward Quest" }
quests[35526] = { id = 35526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Botanica Reward Quest" }
quests[35527] = { id = 35527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitel II: Die Ernte", description = "Ich habe eine Kreatur gesehen, die mit den Schösslingen der Urtume arbeitet. Sie erfüllt sie mit Zorn und Hass gegen alle Kreaturen, die nicht wie sie sind.\n\nVielleicht ist dieser Botani ja für das ungewöhnlich aggressive Verhalten der Urtume hier im Schlingenherz verantwortlich.\n\nOb es uns wohl weiterhelfen würde, diesen Botani zu töten? Allein wäre ich dieser Kreatur jedenfalls nicht gewachsen.\n\n- Frenna", sourceObjective = "Tötet Ontogen den Ernter.", completion = "Der alte große böse Botani ist erledigt? Wunderbar!", sourceObjectiveStatus = "unverified-source-field" }
