quests[35535] = { id = 35535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arcatraz Reward Quest" }
quests[35536] = { id = 35536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Botani", description = "Die Botani müssen diesen riesigen Ogron als Wache für irgendetwas Wertvolles aufgestellt haben. Und was war das für eine plump aussehende Kreatur, die er gerade getötet hat?\n\nDie Botani mögen fies sein, aber das Spielzeug, das sie haben, ist immer erste Sahne. Vielleicht hat Kaz eine Ahnung, was es war.\n\nKönnen wir jetzt nach Kaz suchen?\n\nIch habe einen Komposthaufen auf der südlichen Anhöhe gesehen. Wenn Kaz nach mir suchen würde, würde sie bestimmt dort anfangen.", sourceObjective = "Eskortiert Schlitzer zu Kaz der Kreischenden am Komposthaufen.", completion = "Ihr habt meinen Schlitzer gefunden! Euch zu Ehren werde ich mit Freuden eintausend Kehlen durchschneiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[35537] = { id = 35537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuigkeiten von den Spitzen von Arak", description = "Kommandant, Späher sind von den Spitzen von Arak mit Neuigkeiten in die Garnison zurückgekehrt. Es soll sich ein Krieg zwischen den Vogelmenschen und den Orcs der Zerschmetterten Hand zusammenbrauen.\n\nRokhan möchte gerne mit Euch sprechen, wenn Eure Arbeit hier getan ist... und Ihr dazu gewillt seid.", sourceObjective = "Sprecht mit Rokhan in Eurer Garnison im Frostfeuergrat.", completion = "Willkommen zurück, Scheff.\n\nIch weiß, Ihr wollt hier vermutlich erst alles zu Ende bring'n, aber auf den Spitzen von Arak soll es Aufruhr geb'n. Vielleicht ham' wir ja Glück und find'n dort Verbündete?\n\nIch dacht' mir einfach, ich erzähl' Euch mal davon.", sourceObjectiveStatus = "unverified-source-field" }
