quests[35548] = { id = 35548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mana-Tombs Bonus Objective" }
quests[35549] = { id = 35549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ehrung eines Helden", description = "Beim Licht!\n\nIch kann nicht glauben, dass Taylor und seinen Mannen so etwas mit einer kompletten Garnison zustoßen konnte.\n\nWir werden alle verfügbaren Mittel aufbringen müssen, um Euren Außenposten zu schützen, Kommandant.\n\nWir sollten von hier verschwinden. Wir können die Gefallenen auch noch ehren, wenn wir wieder in Sicherheit sind.", sourceObjective = "Sprecht mit Leutnant Willem in Südhafen.", completion = "Wir werden niemals die Opfer vergessen, die Admiral Taylor für das Wohl aller gebracht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[35550] = { id = 35550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überleben in einem wilden Land", description = "Sie mög'n ja der Allianz angehört hab'n, aber Admiral Taylor und seine Männer hab'n eine ehrenvolle Schlacht geschlag'n.\n\nSie verdien'n unseren Respekt, beim Kriegshäuptling!\n\nWenn eine ganze Garnison der Dunkl'n Magie unterliegt, dürft'n wir alle Hände voll zu tun krieg'n, Kommandant!\n\nWir sollt'n zur Basis zurückkehr'n. Dort is' es sicher...\n\nOder zumindest sicherer.", sourceObjective = "Sprecht mit Zuchtmeister Gornek in Axtfall.", completion = "Ukambe hat mir Bericht erstattet, Kommandant. Ihr seid ein wahrer Champion der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[35552] = { id = 35552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertraut niemandem", description = "Seit meiner Rückkehr ist alles anders. Überall höre ich dieses Flüstern – überall, Flüstern. Maraad kann es nicht sehen, aber hier in Elodor gibt es sogar Spuren teuflischer Energie. Wir wurden unterwandert!\n\nIch muss dem Exarchenrat beiwohnen, doch zuvor müsst Ihr etwas für mich herausfinden. Folgt der teuflischen Energiespur, die ich Euch aufzeigen werde. Wenn sich tatsächlich Verräter in unseren Reihen befinden, brauchen sie ein Versteck. Findet es! Ich warte bei den anderen Exarchen auf Euch.", sourceObjective = "Folgt Maladaars Spur und klärt, ob Elodor unterwandert wurde.", completion = "Ein in Fleisch gebundenes Buch liegt auf einem unheiligen Altar. Euch überkommt eine Gänsehaut. Maladaar hatte recht!", sourceObjectiveStatus = "unverified-source-field" }
quests[35553] = { id = 35553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Rai'vosh" }
quests[35554] = { id = 35554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuigkeiten von den Spitzen von Arak", description = "Während Eurer Abwesenheit ist ein etwas zwielichtiger Mensch am Außenposten aufgetaucht und hat nach Euch gefragt. Er meinte, er arbeite für jemanden namens... Grau, glaub ich?... und hätte Informationen zu den Spitzen von Arak, die Euch interessieren würden.\n\nEr hat sich auf den Weg zu Eurer Garnison gemacht und hat mich deshalb gebeten, Euch diese Nachricht auszurichten.\n\nBevor Ihr geht, wollte ich Euch noch herzlich für alles danken, was Ihr für uns getan habt. Ihr und Eure Armee habt den Ausgang eines Kriegs gewendet, obwohl Ihr ihm auch einfach hättet den Rücken kehren können. Das werden wir Euch nicht vergessen.", sourceObjective = "Sprecht mit Bodrick Grau in Eurer Garnison im Schattenmondtal.", completion = "Willkommen, Kommandant.\n\nIhr wollt Euch bestimmt erst hier um alles kümmern, aber wir haben Berichte über einen Aufstand in den Spitzen von Arak erhalten. Wenn wir jetzt handeln, könnten wir Verbündete finden, die uns im Kampf gegen die Eiserne Horde unterstützen werden.\n\nIch werde die Späher bitten, Bericht zu erstatten, sobald sie mehr erfahren. Das wär's für den Moment, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[35555] = { id = 35555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Dunkelkralle" }
quests[35556] = { id = 35556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse von Gorgrond", description = "Kommandant, Yrel und Maraad haben einen strategischen Vorschlag.\n\nSie empfehlen, eine kleine Expeditionsgruppe in das wilde Ödland von Gorgrond hoch im Norden zu entsenden.\n\nBerichte ihrer Rangari lassen vermuten, dass es dort uralte Geheimnisse oder ursprüngliches Wissen gibt, das uns dabei helfen könnte, unerwartete Schwächen der Eisernen Horde auszunutzen.\n\nWenn Ihr selbst aufbrechen wollt, werde ich sofort einen Greifen für Euch bereitmachen lassen.", sourceObjective = "Sucht Yrel am Wildwuchsbett in Gorgrond auf. Sprecht mit dem Greifenmeister Eurer Garnison, um dorthin zu fliegen.", completion = "Willkommen in Gorgrond, Kommandant. Wir sind selbst gerade erst angekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35557] = { id = 35557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse von Gorgrond", description = "Kommandant, Durotan bittet um Hilfe. Er möchte, dass ein kleiner Stoßtrupp nach Gorgrond hineingeführt wird, um einen Gegenangriff gegen die dortigen Festungen der Eisernen Horde zu führen.\n\nDas Land ist die Heimat des Schwarzfelsklans, dem Industriezweig der Eisernen Horde.\n\nAußerdem gibt es dort einige der wildesten Riesen und Monster von ganz Draenor.\n\nSolltet Ihr diesem Schlachtruf folgen wollen, erreicht Ihr Gorgrond durch den östlichen Teil des Frostfeuergrats über den Donnerpass.", sourceObjective = "Trefft Euch mit Durotan in Gorgrond.", completion = "Gorgrond ist kein Ort für eine Armee, Kommandant. Wir betreten nun die Stätte der Legenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[35558] = { id = 35558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Hypnoquak" }
