quests[35610] = { id = 35610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonusbelohnung: Uldaman" }
quests[35611] = { id = 35611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr ins Terokkversteck", description = "<Am Fuß des Kaliri ist eine kleine Notiz.>\n\n\"Percy hätte einen Warenkorb mitbringen sollen, es sei denn, er hat ihn irgendwo fallen gelassen. Der Inhalt ist als Zeichen meines Dankes und Entschuldigung für die Auseinandersetzung mit Eurem Späher zu verstehen.\n\nIch muss Euch bitten, schleunigst zum Terokkversteck zurückzukehren, damit wir unsere Pläne vorantreiben können.\n\n- Reshad \"", sourceObjective = "Sprecht mit Reshad im Terokkversteck.", completion = "Danke, dass Ihr zu uns zurückgekehrt seid, {name}. Ich muss zugeben, dass wir dringendst auf Eure Hilfe angewiesen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[35612] = { id = 35612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Monastery Reward Quest" }
quests[35613] = { id = 35613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Monastery Reward Quest" }
quests[35614] = { id = 35614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstrukteur Romuul", sourceObjective = "Ich habe von Euch gehört, Reisender. Eure Leute sind hier, um die Eiserne Horde zu besiegen.\n\nEure Kampffähigkeiten, die Ihr gerade an den Tag gelegt habt, stehen Eurem Ruf in nichts nach.\n\nAuch ich wünsche mir, dass die Eiserne Horde von hier verschwindet. Ich werde die Kraft meines Hammers in Euren Dienst stellen, und auch mein Wissen über die Kristallbearbeitung mag sich als nützlich erweisen.\n\nWas meint Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[35615] = { id = 35615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razorfen Kraul Reward Quest" }
quests[35616] = { id = 35616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand – Schatz 029 – Dampfdruckvorräte" }
quests[35617] = { id = 35617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiona", sourceObjective = "Ich habe mit den anderen Mitgliedern meiner Karawane gesprochen und wir sind bereit, unsere Reise eine Zeit lang zu unterbrechen, damit ich Eurer Garnison dienen kann.\n\nIch denke, ich könnte Euch eine große Hilfe sein. Was meint Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[35618] = { id = 35618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gidwin Goldzopf", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[35619] = { id = 35619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkstatt Quetschpfeif", description = "Kommandant, ein Goblinkurier ist heute Morgen eingetroffen.\n\nEr sagte, er kommt aus einer Siedlung im Südosten, die sich Werkstatt Quetschpfeif nennt. Man bittet dort wegen irgendeiner Naturkatastrophe um unsere Hilfe.\n\nWenn wir ihr Vertrauen gewinnen können, wäre das die Mühe wert. Begebt Euch dorthin und schaut nach, welche Hilfe wir leisten können.\n\nIch habe bereits mit dem Flugmeister gesprochen, der einen Sonderflug für Euch dorthin veranlasst hat.", sourceObjective = "Sprecht mit Firn Windflitzer, um Euren Flug zur Werkstatt Quetschpfeif anzutreten.", completion = "Heh, Ihr seid von dieser Allianzbasis, richtig?\n\nIch bin froh, dass Ihr die Reise angetreten habt, wir können hier nämlich wirklich Eure Hilfe brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[35620] = { id = 35620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkstatt Quetschpfeif", description = "Kommandant, ein Kurier ist heute Morgen eingetroffen.\n\nEr sagte, er kommt aus einer Goblinsiedlung im Südosten, die sich Werkstatt Quetschpfeif nennt. Man bittet dort wegen irgendeiner Naturkatastrophe um unsere Hilfe.\n\nWir haben zwar nur wenig Leute, aber wenn wir ihr Vertrauen gewinnen können, bekommen wir vielleicht einen wertvollen Verbündeten.\n\nBegebt Euch dorthin und schaut nach, welche Hilfe wir leisten können. Ich habe bereits mit dem Flugmeister gesprochen, der einen Sonderflug für Euch dorthin veranlasst hat.", sourceObjective = "Sprecht mit Hutou Federwind, um Euren Flug zur Werkstatt Quetschpfeif anzutreten.", completion = "Heh, Ihr seid von dieser Hordenbasis, richtig?\n\nIch bin froh, dass Ihr die Reise angetreten habt, wir können hier nämlich wirklich Eure Hilfe brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[35621] = { id = 35621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarenar Sonnenhieb", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
