quests[35623] = { id = 35623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand – Vignette Boss – Forscher Rixak" }
quests[35624] = { id = 35624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roona" }
quests[35625] = { id = 35625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shelly Hamby", sourceObjective = "Draenor... Sogar der Name dieses Ortes macht mich krank.\n\nMein Mann ist fort und ich kann nicht nach Hause zurückkehren, solange der Schmerz an sein Andenken noch in meiner Seele brennt.\n\nBitte, ich will mich Euch anschließen und für Euch kämpfen. Schickt mich an die Front, wann immer Ihr möchtet, dass dort die Köpfe Eurer Feinde rollen.\n\nJeder Feind, den ich besiege, lindert vielleicht meinen Schmerz.", sourceObjectiveStatus = "unverified-source-field" }
quests[35626] = { id = 35626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstrukteurslehrling Andren", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[35627] = { id = 35627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Korb mit Arakkoawaren" }
quests[35628] = { id = 35628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rangari Chel", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[35629] = { id = 35629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigerin Onaala", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[35630] = { id = 35630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Visitor: Sappy" }
quests[35631] = { id = 35631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rulkan", sourceObjective = "Prophet Velen schätzt Euch sehr und ich sehe, dass Ihr mit Euren Waffen umzugehen wisst. Auch Eure Absichten scheinen ehrenwert zu sein.\n\nIch spüre, dass gewaltige Kräfte in Euch schlummern. Wenn Ihr nichts dagegen habt, würde ich gerne meine Hände ein Weilchen an Eurem Feuer wärmen.\n\nIch möchte mich Euch gerne anschließen und von Euren Leuten lernen. Im Gegenzug werde ich für Euch kämpfen.\n\nWas sagt Ihr, Reisender?", sourceObjectiveStatus = "unverified-source-field" }
quests[35632] = { id = 35632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lektion in Archäologie", description = "Als Archäologe ist es wichtig, große Entdeckungen zu machen und seinen Beitrag in dem Gebiet zu leisten. Warum? Weil man sich so einen Namen macht!\n\nSogar dieser Schreiberling Harrison Jones hat sich einen einigermaßen ordentlichen Ruf erarbeitet. Wenn der das schafft, so könnt Ihr das auch!\n\nDie Hochfelsoger verstecken etwas Großes in ihren Höhlen, und wir müssen dort rein und es holen!\n\nNehmt dieses Teleportersignal und schlagt Euch bis zum hinteren Teil der Höhle durch. Wenn Ihr das Relikt findet, platziert das Signal und mein Team wird sich um den Rest kümmern!", sourceObjective = "Bergt das mysteriöse Artefakt.", completion = "Gute Arbeit! So sieht echte Archäologie aus!\n\nGut, dass Ihr zu mir gekommen seid, um das Handwerk zu lernen, Kleiner. Ihr habt Talent und es wäre doch wirklich furchtbar, wenn ich zusehen müsste, wie Ihr es an diesen Trottel Harrison Jones verschwendet!", sourceObjectiveStatus = "unverified-source-field" }
quests[35633] = { id = 35633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherforensik", description = "Meine gesamte Einheit ist weg. Einige meiner Leute sind tot, aber die anderen... sie müssen weiter drinnen sein.\n\nGeht und durchsucht die Leichen meiner Leute. Jeder meiner Männer sollte einen kleinen Beutel mit persönlichen Dingen bei sich gehabt haben, die ich gerne ihren Familien zurückgeben möchte.\n\nIch mache mich schon auf den Weg, wir treffen uns dann im Sumpf.", sourceObjective = "Sammelt 5 Rangari-Beutel von toten Rangari.", progress = "Die Familien meiner Einheit müssen wissen, was ihren Angehörigen widerfahren ist. Ich brauche zuverlässige Informationen über ihren Tod.", completion = "Danke für Eure Hilfe, {name}. Hoffentlich lassen sich diese widerlichen Sporen entfernen, die hier alles bedecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[35634] = { id = 35634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontrolle ist alles", description = "Diese Apexistechnologie ist erstaunlich, oder? Von Sonnenenergie angetriebene Maschinen. Mit Magie verstärkte Energie!\n\nEinfach brillant!\n\nAh, aber es gibt ja immer einen Haken. Und ich glaube, dass Ihr ihn gefunden habt.\n\nKönnt Ihr bitte das Schnittstellengerät in das Terokkversteck bringen? Ich werde bald mit den Apexiskernen nachkommen.\n\nWenn meine Theorie stimmt, können wir die Waffe der Jünger gegen sie selbst richten!", sourceObjective = "Bringt die Apexissteuerung zu Dunkelseher Raastok im Terokkversteck.", progress = "Habt Ihr das Gerät dabei?", completion = "Es wird etwas dauern, aber das könnte der Schlüssel zum Sieg sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[35636] = { id = 35636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bei allem Respekt", description = "Eine Gruppe von Jüngern war kurz vor dem Angriff auf Skettis hier. Hab mich als Pilz getarnt. Die Dummköpfe sind direkt an mir vorbei gelaufen.\n\nMein Nachbar ein Stück weiter die Straße rauf hatte nicht so viel Glück.\n\nHat immer viel gelesen. Vielleicht sind in seiner Hütte ja noch wertvolle Informationen. Gebt Reshad etwas Zeit, sich dort umzusehen.\n\nAch ja, und bringt doch bitte ein paar seiner Federn zum Schrein in der Nähe des Terokkverstecks, ja? Er war so ein netter Kerl und hätte das sicher so gewollt.", sourceObjective = "Findet die Feder von Syth und die Sage von Terokk.", progress = "Gut, ich werde beide nehmen und sicher verwahren.", completion = "<Reshad legt die Feder in den Folianten, bevor er diesen in seiner Robe verschwinden lässt.>\n\nVor dem Wegschrein müssen wir noch an einem anderen Ort vorbei...", sourceObjectiveStatus = "unverified-source-field" }
